import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students each hold one cookie of every one of {m} distinct shapes. For every student i there is a single preferred shape p_i. The mass of the cookie of that preferred shape is h, while the mass of each of the other {m} − 1 cookies is the same value l = {l_num}/{l_den}. All students share the same h and l, with h and l positive and satisfying h + ({m} − 1)·l = 1 and h > l. You must select exactly one cookie from each student. If a student is assigned to their preferred shape, that student contributes mass h to that shape’s total; if assigned to any non-preferred shape, they contribute mass l to that shape’s total.\n\nLet C be the smallest positive real number such that, no matter how the preferred shapes p_i are arranged among the {m} shapes, it is always possible to select one cookie from each student so that, for every shape, the total mass of the selected cookies of that shape does not exceed C. Write C in simplest fractional form q/p and report p + q.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate alpha (students), m (shapes), and l = a/b with 0 < l < 1/m to ensure h = 1 - (m-1)l > l > 0.
# Retry until constraints are met.
for _ in range(1000):
    alpha = rng.randint(400, 5000)
    m = rng.randint(5, 150)
    # Choose denominator b reasonably large
    b = rng.randint(m + 2, 200)
    # a must satisfy 1 <= a <= floor((b-1)/m) so that l < 1/m and h > 0
    max_a = (b - 1) // m
    if max_a < 1:
        continue
    a = rng.randint(1, max_a)
    # Ensure l is in simplest form
    import math
    g = math.gcd(a, b)
    a //= g
    b //= g
    # Re-check after reduction that l < 1/m
    if a * m >= b:
        continue
    # h positive check: h_num = b - (m-1)*a > 0
    h_num = b - (m - 1) * a
    if h_num <= 0:
        continue
    return {
        'alpha': alpha,
        'm': m,
        'l_num': a,
        'l_den': b
    }
# Fallback deterministic safe choice if randomness fails
alpha = 1000
m = 10
a = 1
b = 15  # l = 1/15 < 1/10, h = 1 - 9/15 = 6/15 > l
return {
    'alpha': alpha,
    'm': m,
    'l_num': a,
    'l_den': b
}

    def verifier(assign):
# Validate inputs and compute the answer C = max(h * floor(alpha/m), l * ceil(alpha/m)) in simplest form.
try:
    alpha = int(assign['alpha'])
    m = int(assign['m'])
    a = int(assign['l_num'])
    b = int(assign['l_den'])
except Exception:
    # Invalid assignment structure
    return (False, None)
# Basic domain checks
if alpha <= 0 or m <= 1 or a <= 0 or b <= 0:
    # invalid ranges
    return (False, None)
# Check l < 1/m and positivity
if a * m >= b:
    # l >= 1/m would break h > l and could make h non-positive
    return (False, None)
# Compute h = 1 - (m-1) * l = (b - (m-1)*a) / b
h_num = b - (m - 1) * a
h_den = b
if h_num <= 0:
    return (False, None)
# floor and ceil of alpha/m
floor_nm = alpha // m
ceil_nm = (alpha + m - 1) // m
# Candidate bounds
# c1 = h * floor_nm = (h_num * floor_nm) / b
# c2 = l * ceil_nm = (a * ceil_nm) / b
c1_num = h_num * floor_nm
c2_num = a * ceil_nm
# Max of the two since same denominator b
max_num = c1_num if c1_num >= c2_num else c2_num
max_den = b
# Reduce the fraction
import math
g = math.gcd(max_num, max_den)
p = max_den // g
q = max_num // g
answer = p + q
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
